import { Injectable, NgZone } from '@angular/core';
import { HttpClient, HttpErrorResponse, HttpHeaders, HttpResponse } from '@angular/common/http';
import { Observable, catchError, first, map, mergeMap, throwError } from 'rxjs';
import { webSocket } from 'rxjs/webSocket';
import { Router } from '@angular/router';

import { processServiceError } from '../utils/errors';
import { SnackbarService } from './snackbar.service';
import { environment } from 'src/environments/environment';

export enum ResponseTypes {
  Json = 'json',
  Text = 'text',
}

export enum RequestTypes {
  Json = 'json',
  // RawJson sends the body as-is (must already be a JSON-encoded
  // string). Avoids the double JSON.stringify the default Json mode
  // would do — useful when the caller wants the user's exact bytes
  // preserved on the wire (e.g. the runtime-config editor).
  RawJson = 'raw-json',
}

export class RequestOptions {
  responseType = ResponseTypes.Json;
  requestType = RequestTypes.Json;
  ignoreAuth = false;
  vpnKeyForAuth!: string | null;
  csrfToken!: string;

  public constructor(init?: Partial<RequestOptions>) {
    Object.assign(this, init);
  }
}

/**
 * Allows to make requests to the backend API.
 */
@Injectable({
  providedIn: 'root'
})
export class ApiService {
  /**
   * URL prefix for the API routes. The 'http-api/' prefix is used if the app is running
   * with the dev server using the http protocol, because the dev server proxy uses it to
   * route the request to the appropiate url.
   */
  public readonly apiPrefix = !environment.production && location.protocol.indexOf('http:') !== -1 ?
    'http-api/' : 'api/';

  /**
   * Similar to apiPrefix, but for web sockets.
   */
  private readonly wsApiPrefix = !environment.production ?
    (location.protocol.indexOf('http:') !== -1 ? 'ws-api/' : 'wss-api/') :
    'api/';

  constructor(
    private http: HttpClient,
    private router: Router,
    private ngZone: NgZone,
    private snackbar: SnackbarService,
  ) { }

  /**
   * Makes a request to a GET endpoint.
   * @param url Endpoint URL, after the "/api/" part.
   */
  get(url: string, options: RequestOptions | null = null): Observable<any> {
    return this.request('GET', url, {}, options);
  }

  /**
   * Makes a request to a POST endpoint.
   * @param url Endpoint URL, after the "/api/" part.
   */
  post(url: string, body: any = {}, options: RequestOptions | null = null): Observable<any> {
    return this.getCsrf().pipe(first(), mergeMap(csrf => {
      options = options ? options : new RequestOptions();
      options.csrfToken = csrf;

      return this.request('POST', url, body, options);
    }));
  }

  /**
   * Makes a request to a PUT endpoint.
   * @param url Endpoint URL, after the "/api/" part.
   */
  put(url: string, body: any = {}, options: RequestOptions | null = null): Observable<any> {
    return this.getCsrf().pipe(first(), mergeMap(csrf => {
      options = options ? options : new RequestOptions();
      options.csrfToken = csrf;

      return this.request('PUT', url, body, options);
    }));
  }

  /**
   * Makes a request to a DELETE endpoint.
   * @param url Endpoint URL, after the "/api/" part.
   */
  delete(url: string, options: RequestOptions | null = null): Observable<any> {
    return this.getCsrf().pipe(first(), mergeMap(csrf => {
      options = options ? options : new RequestOptions();
      options.csrfToken = csrf;

      return this.request('DELETE', url, {}, options);
    }));
  }

  /**
   * Gets a csrf token from the node, to be able to make protected requests.
   */
  private getCsrf(): Observable<string> {
    return this.get('csrf').pipe(map(response => response.csrf_token));
  }

  /**
   * Makes a request to a WebSocket endpoint.
   * @param url Endpoint URL, after the "/api/" part.
   */
  ws(url: string, body: any = {}): Observable<any> {
    const wsProtocol = (location.protocol.startsWith('https')) ? 'wss://' : 'ws://';
    const wsUrl = wsProtocol + location.host + '/' + this.wsApiPrefix + url;
    const ws = webSocket(wsUrl);

    ws.next(body);

    return ws;
  }

  /**
   * Makes the actual call to the API.
   */
  private request(method: string, url: string, body: any, options: RequestOptions | null) {
    body = body ? body : {};
    options = options ? options : new RequestOptions();

    // Sanitize the URL.
    if (url.startsWith('/')) {
      url = url.substr(1, url.length - 1);
    }

    return this.http.request(method, this.apiPrefix + url, {
      ...this.getRequestOptions(options),
      responseType: options.responseType,
      // Use the session cookies.
      withCredentials: true,
      body: this.getPostBody(body, options),
      observe: 'response',
    } as any).pipe(
      map((response: any) => this.successHandler(this.noteParked(response as HttpResponse<any>))),
      catchError(error => this.errorHandler(error, options)),
    );
  }

  /**
   * Process the options to use them whem making the reques.
   */
  private getRequestOptions(options: RequestOptions) {
    const requestOptions: any = {};

    requestOptions.headers = new HttpHeaders();

    if (options.requestType === RequestTypes.Json || options.requestType === RequestTypes.RawJson) {
      requestOptions.headers = requestOptions.headers.append('Content-Type', 'application/json');
    }

    if (options.csrfToken) {
      requestOptions.headers = requestOptions.headers.append('X-CSRF-Token', options.csrfToken);
    }

    return requestOptions;
  }

  /**
   * Encode the content to send it to the backend.
   */
  private getPostBody(body: any, options: RequestOptions) {
    if (options.requestType === RequestTypes.RawJson) {
      // Caller is responsible for handing us a JSON-encoded string.
      return typeof body === 'string' ? body : JSON.stringify(body);
    }
    if (options.requestType === RequestTypes.Json) {
      return JSON.stringify(body);
    }

    const formData = new FormData();

    Object.keys(body).forEach(key => formData.append(key, body[key]));

    return formData;
  }

  /**
   * A 202 naming an inbox host is a change for an offline visor that waits on
   * its dmsg-async inbox. Says so after any message the caller shows.
   */
  private noteParked(response: HttpResponse<any>): any {
    if (response.status === 202 && response.headers.get('X-Skywire-Parked')) {
      setTimeout(() => this.snackbar.showWarning('common.change-parked'));
    }

    return response.body;
  }

  private successHandler(result: any) {
    if (typeof result === 'string' && result === 'manager token is null') {
      throw new Error(result);
    }

    return result;
  }

  private errorHandler(error: HttpErrorResponse, options: RequestOptions) {
    // Normally, if the problem was due to the session cookie being invalid, the
    // user is redirected to the login page.
    if (!options.ignoreAuth) {
      if (error.status === 401) {
        const destination = !options.vpnKeyForAuth ? ['login'] : ['vpnlogin', options.vpnKeyForAuth];
        this.ngZone.run(() => this.router.navigate(destination, { replaceUrl: true }));
      }

      if (error.error && typeof error.error === 'string' && error.error.includes('change password')) {
        const destination = !options.vpnKeyForAuth ? ['login'] : ['vpnlogin', options.vpnKeyForAuth];
        this.ngZone.run(() => this.router.navigate(destination, { replaceUrl: true }));
      }
    }

    return throwError(processServiceError(error));
  }
}
